export interface Redemption {
  receipt: string;
  message: string;
}

export type VoucherVerifier = (code: string, pin: string) => Promise<string | null>;

export async function redeemVoucher(
  code: string,
  pin: string,
  verify: VoucherVerifier,
): Promise<Redemption> {
  if (code.trim().length === 0 || pin.trim().length === 0) {
    throw new Error("Code and PIN are required.");
  }
  if (!/^[A-Z]{6}$/.test(code)) {
    throw new Error("Invalid voucher code.");
  }
  if (!/^\d{4,}$/.test(pin)) {
    throw new Error("Invalid PIN.");
  }

  const receipt = await verify(code, pin);
  if (receipt === null || receipt.length === 0) {
    throw new Error("Voucher was rejected.");
  }
  return { receipt, message: "Voucher redeemed." };
}

