import { redeemVoucher, VoucherVerifier } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: unexpected value`);
}
async function rejectsWith(promise: Promise<unknown>, expected: unknown, message: string): Promise<void> {
  let caught: unknown;
  try { await promise; } catch (error) { caught = error; }
  if (expected instanceof Error) {
    assert(caught instanceof Error && caught.message === expected.message, message);
  } else {
    assert(caught === expected, message);
  }
}

async function run(): Promise<void> {
  const calls: Array<[string, string]> = [];
  const verify: VoucherVerifier = async (code, pin) => {
    calls.push([code, pin]);
    return "receipt-1";
  };
  deepEqual(await redeemVoucher("ABCDEF", "0123", verify), { receipt: "receipt-1", message: "Voucher redeemed." }, "successful redemption");
  deepEqual(calls, [["ABCDEF", "0123"]], "verifier called once with original values");

  let validationCalls = 0;
  const shouldNotRun: VoucherVerifier = async () => { validationCalls += 1; return "unexpected"; };
  const invalidCases: Array<[string, string, string]> = [
    ["", "1234", "Code and PIN are required."],
    ["   ", "1234", "Code and PIN are required."],
    ["ABCDEF", "\t", "Code and PIN are required."],
    ["ABCDE", "1234", "Invalid voucher code."],
    ["abcdef", "1234", "Invalid voucher code."],
    ["ABCDE1", "1234", "Invalid voucher code."],
    ["ABCDEFG", "1234", "Invalid voucher code."],
    ["ABCDEF", "123", "Invalid PIN."],
    ["ABCDEF", "12345", "Invalid PIN."],
    ["ABCDEF", "12a4", "Invalid PIN."],
    ["ABCDEF", "１２３４", "Invalid PIN."],
  ];
  for (const [code, pin, message] of invalidCases) {
    await rejectsWith(redeemVoucher(code, pin, shouldNotRun), new Error(message), `${code}/${pin} validation`);
  }
  assert(validationCalls === 0, "local validation must not call verifier");

  let rejectionCalls = 0;
  const rejected = new Error("verifier unavailable");
  const rejectingVerifier: VoucherVerifier = async () => { rejectionCalls += 1; throw rejected; };
  await rejectsWith(redeemVoucher("QWERTY", "9876", rejectingVerifier), rejected, "verifier rejection identity is propagated");
  assert(rejectionCalls === 1, "rejecting verifier called once");

  await rejectsWith(redeemVoucher("ABCDEF", "1234", async () => null), new Error("Voucher was rejected."), "null receipt rejected");
  await rejectsWith(redeemVoucher("ABCDEF", "1234", async () => ""), new Error("Voucher was rejected."), "empty receipt rejected");
  deepEqual(await redeemVoucher("ABCDEF", "1234", async () => " "), { receipt: " ", message: "Voucher redeemed." }, "non-empty whitespace receipt accepted");
}

void run().catch((error) => { throw error; });

